  "implementation": "def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_by_id = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        p = n['parent']
        if p is not None:
            children.setdefault(p, []).append(n['id'])
    root_id = next(n['id'] for n in nodes if n['parent'] is None)
    retained = set(node_by_id.keys())
    candidates = [n for n in nodes if n['removable'] and n['symbol'] not in required and n['id'] != root_id]
    candidates.sort(key=lambda n: (-n['depth'], n['id']))
    removed = []
    for n in candidates:
        nid = n['id']
        if nid not in retained:
            continue
        if any(c in retained for c in children.get(nid, [])):
            continue
        retained.discard(nid)
        removed.append(nid)
    return {'removed_node_ids': removed, 'retained_node_ids': sorted(retained)}"
